import{_ as t,o,c as a,a3 as s}from"./chunks/framework.BTQ4eCVb.js";const u=JSON.parse('{"title":"Opportunities — User Guide","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Opportunities — User Guide | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/user-guide/opportunities"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Opportunities — User Guide | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/user-guide/opportunities"}]]},"headers":[],"relativePath":"user-guide/opportunities.md","filePath":"user-guide/opportunities.md","lastUpdated":1788619224000}'),n={name:"user-guide/opportunities.md"};function r(i,e,l,d,p,c){return o(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="opportunities-—-user-guide" tabindex="-1">Opportunities — User Guide <a class="header-anchor" href="#opportunities-—-user-guide" aria-label="Permalink to &quot;Opportunities — User Guide&quot;">​</a></h1><h2 id="who-can-use-opportunities" tabindex="-1">Who can use Opportunities <a class="header-anchor" href="#who-can-use-opportunities" aria-label="Permalink to &quot;Who can use Opportunities&quot;">​</a></h2><p>Your workspace must have the <strong>Opportunities</strong> module installed (free from Marketplace — not auto-installed). Your role must include the relevant permissions (<code>view</code>, <code>create</code>, <code>update</code>, <code>delete</code>, <code>restore</code>, <code>force.delete</code>, <code>assign</code> as needed).</p><p>Without <strong>assign</strong>, you only see opportunities assigned to you.</p><h2 id="board-table" tabindex="-1">Board &amp; table <a class="header-anchor" href="#board-table" aria-label="Permalink to &quot;Board &amp; table&quot;">​</a></h2><p>Open <strong>Opportunities</strong> from the sidebar (Sales). The default view is the <strong>Kanban board</strong> (columns = pipeline stages). Switch to <strong>Table</strong> when you prefer a list.</p><ul><li>Search by deal name</li><li>Each stage column header and its cards use that stage’s color; Stage badges in the table and record page use the same colors</li><li>Filter by stage, assignee, <strong>tag</strong>, related Contact / Company / Lead, or toggle <strong>My Opportunities</strong></li><li>KPI cards summarize totals, open / won / lost, pipeline value, weighted pipeline, won value, and conversion rate for your scope</li><li>Table and board show <strong>tags</strong> and the <strong>latest note</strong>; hover a truncated preview to read the full note</li><li>Users with <strong>restore</strong> can filter <strong>Active / Include deleted / Deleted only</strong>, then <strong>Restore</strong> a soft-deleted opportunity from the row menu</li><li><strong>Delete permanently</strong> requires <code>opportunities.force.delete</code> — granted to the workspace <strong>owner</strong> by default</li></ul><h2 id="create-edit" tabindex="-1">Create &amp; edit <a class="header-anchor" href="#create-edit" aria-label="Permalink to &quot;Create &amp; edit&quot;">​</a></h2><ol><li>Click <strong>New opportunity</strong></li><li>Enter name (required) and optional amount, currency, probability (0–100), and expected close date</li><li>Optionally set stage and assignee (assignee requires <strong>assign</strong>)</li><li>Optionally link a <strong>Contact</strong>, <strong>Company</strong>, and/or <strong>Lead</strong> (pickers appear when those modules are installed — use <strong>New</strong> beside a picker to create and select inline when you have that module’s create permission)</li><li>Optionally assign <strong>tags</strong> (colored labels). Create a new tag inline with a name and color, then tick it</li><li>Save</li></ol><p>Edit from the row menu or the record page.</p><p>Tags are an <strong>Opportunities-only</strong> catalog (separate from Leads disposition tags and Tasks / ToDos tags). In this release you can <strong>create and assign</strong> tags inline; there is no Manage Tags screen to rename or delete them. The record page shows tag badges — change assignments from Edit.</p><h2 id="sales-pipeline-stages" tabindex="-1">Sales pipeline (stages) <a class="header-anchor" href="#sales-pipeline-stages" aria-label="Permalink to &quot;Sales pipeline (stages)&quot;">​</a></h2><p>Pipeline stages are part of Opportunities — there is no separate “Sales Pipeline” product.</p><p>Seeded stages: <strong>Prospecting</strong> (default) → <strong>Qualification</strong> → <strong>Proposal</strong> → <strong>Negotiation</strong> → <strong>Won</strong> / <strong>Lost</strong>.</p><ul><li>Moving a card on the board auto-saves the stage change (same as <a href="/user-guide/leads">Leads</a>); click a card to open the drawer for edits</li><li>Won / Lost columns mark closed deals for KPIs (pipeline value excludes them)</li></ul><h2 id="assignment" tabindex="-1">Assignment <a class="header-anchor" href="#assignment" aria-label="Permalink to &quot;Assignment&quot;">​</a></h2><p>Users with <strong>assign</strong> can set or clear the assignee from the record page or the create/edit form. The assignee receives an in-app notification when someone else assigns them.</p><h2 id="notes-activity" tabindex="-1">Notes &amp; activity <a class="header-anchor" href="#notes-activity" aria-label="Permalink to &quot;Notes &amp; activity&quot;">​</a></h2><ul><li><strong>Notes</strong> — free-form notes on the deal</li><li><strong>Activity</strong> — timeline of create, update, assignment, stage change, note, and delete/restore events</li></ul>',19)])])}const h=t(n,[["render",r]]);export{u as __pageData,h as default};
